import type { DbMode } from './env.js'

export const GENERATED_MARKER =
  '# generated by nextgin — edits are overwritten; remove this line to take ownership'

export interface StackOptions {
  name: string
  image: string
  postgres: DbMode
  redis: DbMode
  domain?: string
  dbName: string
}

/**
 * Returns true when a generated file does not exist yet or still begins with GENERATED_MARKER.
 */
export function canOverwriteGenerated(existing: string | undefined): boolean {
  if (existing === undefined) return true
  const firstLine = existing.split(/\r?\n/, 1)[0]
  return firstLine === GENERATED_MARKER
}

/**
 * Normalizes a project name into a safe Postgres database identifier.
 */
export function dbNameFor(name: string): string {
  let db = name.toLowerCase().replace(/[^a-z0-9_]/g, '_')
  if (/^[0-9]/.test(db)) {
    db = `app_${db}`
  }
  db = db.slice(0, 40)
  return db.length === 0 ? 'app' : db
}

/**
 * Generates the runtime-only Dockerfile for `nextgin deploy`.
 */
export function generateDockerfile(): string {
  return `${GENERATED_MARKER}
FROM node:22-bookworm-slim
WORKDIR /app
COPY --chown=node:node server /app/server
COPY --chown=node:node .nextgin /app/.nextgin
ENV PORT=8080
ENV GIN_MODE=release
USER node
EXPOSE 8080
HEALTHCHECK --interval=10s --timeout=5s --start-period=30s --retries=5 CMD node -e "fetch('http://127.0.0.1:8080/').then(r=>process.exit(r.status<500?0:1)).catch(()=>process.exit(1))"
ENTRYPOINT ["/app/server"]
`
}

function yamlQuote(value: string): string {
  if (/[:$]/.test(value)) {
    return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`
  }
  return value
}

/**
 * Generates `docker-compose.yml` for the VPS stack.
 */
export function generateCompose(o: StackOptions): string {
  const hasPostgres = o.postgres === 'internal'
  const hasRedis = o.redis === 'internal'
  const hasDomain = o.domain !== undefined

  const lines: string[] = [
    GENERATED_MARKER,
    `name: nextgin-${o.name}`,
    'services:',
    '  app:',
    `    image: ${yamlQuote(o.image)}`,
    '    restart: unless-stopped',
    '    env_file: [.env]',
  ]

  if (hasPostgres || hasRedis) {
    lines.push('    depends_on:')
    if (hasPostgres) {
      lines.push('      postgres:')
      lines.push('        condition: service_healthy')
    }
    if (hasRedis) {
      lines.push('      redis:')
      lines.push('        condition: service_healthy')
    }
  }

  if (!hasDomain) {
    lines.push('    ports: ["80:8080"]')
  }

  if (hasPostgres) {
    lines.push(
      '  postgres:',
      `    image: ${yamlQuote('postgres:16')}`,
      '    restart: unless-stopped',
      '    environment:',
      '      POSTGRES_USER: nextgin',
      `      POSTGRES_DB: ${o.dbName}`,
      '      POSTGRES_PASSWORD: "${POSTGRES_PASSWORD}"',
      '    volumes: ["pgdata:/var/lib/postgresql/data"]',
      '    healthcheck:',
      `      test: ["CMD-SHELL", "pg_isready -U nextgin -d ${o.dbName}"]`,
      '      interval: 5s',
      '      timeout: 5s',
      '      retries: 20',
    )
  }

  if (hasRedis) {
    lines.push(
      '  redis:',
      `    image: ${yamlQuote('redis:7')}`,
      '    restart: unless-stopped',
      '    environment:',
      '      REDIS_PASSWORD: "${REDIS_PASSWORD}"',
      '    command: ["redis-server", "--requirepass", "${REDIS_PASSWORD}", "--appendonly", "yes"]',
      '    volumes: ["redisdata:/data"]',
      '    healthcheck:',
      '      test: ["CMD-SHELL", "redis-cli -a \\"$$REDIS_PASSWORD\\" ping | grep PONG"]',
      '      interval: 5s',
      '      timeout: 5s',
      '      retries: 20',
    )
  }

  if (hasDomain) {
    lines.push(
      '  caddy:',
      `    image: ${yamlQuote('caddy:2')}`,
      '    restart: unless-stopped',
      '    ports: ["80:80", "443:443"]',
      '    volumes: ["./Caddyfile:/etc/caddy/Caddyfile:ro", "caddy_data:/data", "caddy_config:/config"]',
      '    depends_on: [app]',
    )
  }

  const volumes: string[] = []
  if (hasPostgres) volumes.push('pgdata')
  if (hasRedis) volumes.push('redisdata')
  if (hasDomain) volumes.push('caddy_data', 'caddy_config')

  if (volumes.length > 0) {
    lines.push('volumes:')
    for (const v of volumes) {
      lines.push(`  ${v}:`)
    }
  }

  return `${lines.join('\n')}\n`
}

/**
 * Generates a Caddyfile reverse-proxying `domain` to `app:8080`.
 */
export function generateCaddyfile(domain: string): string {
  return `${GENERATED_MARKER}\n${domain} {\n\treverse_proxy app:8080\n}\n`
}
